class TenantView(APIView):
    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)

        # بعد از احراز هویت
        tenant_slug = request.headers.get("X-Tenant")
        if not tenant_slug:
            raise ValidationError({"X-Tenant": "الزامی است."})

        try:
            request.tenant = Tenant.objects.get(slug=tenant_slug)
        except Tenant.DoesNotExist:
            raise NotFound("Tenant پیدا نشد.")

    def get(self, request):
        return Response({"tenant": request.tenant.slug})

def finalize_response(self, request, response, *args, **kwargs):
    # اگر data خام بود، آن را به Response تبدیل کن
    if isinstance(response, HttpResponseBase):
        return response

    if not isinstance(response, Response):
        response = Response(response)

    # اعمال renderer
    if getattr(request, "accepted_renderer", None) is not None:
        response.accepted_renderer = request.accepted_renderer
        response.accepted_media_type = request.accepted_media_type
        response.renderer_context = self.get_renderer_context()

    # افزودن Vary
    for key, value in self.headers.items():
        response[key] = value

    return response

